IList<int> intList = new List<int>() { 7, 10, 21, 30, 45, 50, 87 };

Console.WriteLine(intList.First());                    // 7
Console.WriteLine(intList.First(i => i % 2 == 0));    // 10 (first even)

// emptyList.First() throws InvalidOperationException

IList<int> intList = new List<int>() { 7, 10, 21, 30, 45, 50, 87 };
IList<string> emptyList = new List<string>();

Console.WriteLine(intList.FirstOrDefault());                    // 7
Console.WriteLine(intList.FirstOrDefault(i => i % 2 == 0));    // 10
Console.WriteLine(emptyList.FirstOrDefault());                  // null (default string)
